import sys,os,json,base64,tempfile,webbrowser,threading,time,pathlib,traceback,queue
import webview

NAME="uygulamam";TITLE="Uygulamam";W=800;H=500;FULL=False;TOP=True;BASLA=False;ICON=""
HTML=base64.b64decode("").decode("utf-8")
if BASLA:
    try:
        import winreg
        k=winreg.OpenKey(winreg.HKEY_CURRENT_USER,r"Software\Microsoft\Windows\CurrentVersion\Run",0,winreg.KEY_SET_VALUE)
        winreg.SetValueEx(k,NAME,0,winreg.REG_SZ,'"'+sys.executable+'"')
    except Exception: pass
base=os.path.join(os.environ.get("APPDATA",tempfile.gettempdir()),"UGCO_"+NAME)
os.makedirs(base,exist_ok=True)
with open(os.path.join(base,"index.html"),"w",encoding="utf-8") as f: f.write(HTML)
PICS=os.path.join(os.path.expanduser("~"),"Pictures",NAME)
os.makedirs(PICS,exist_ok=True)
win=None
EQ=queue.Queue()
def _ejw():
    while True:
        c=EQ.get()
        try: win.evaluate_js(c)
        except Exception: LOG("evaluate_js: "+traceback.format_exc()[-500:])
threading.Thread(target=_ejw,daemon=True).start()
def ej(c): EQ.put(c)
class _B:
    def __init__(s): s.js=s
    def emit(s,c): ej(c)
br=_B()
FD=getattr(webview,"FileDialog",None)
def dlg(kind,**kw):
    if FD: k=FD.OPEN if kind=="open" else FD.SAVE
    else: k=webview.OPEN_DIALOG if kind=="open" else webview.SAVE_DIALOG
    r=win.create_file_dialog(k,**kw)
    if r is None: return []
    return list(r) if isinstance(r,(list,tuple)) else [r]
def LOG(m):
    try:
        with open(os.path.join(base,"hata.txt"),"a",encoding="utf-8") as f: f.write(time.strftime("%H:%M:%S ")+m+"\n")
    except Exception: pass
def PANO(t):
    import ctypes
    u=ctypes.windll.user32; kk=ctypes.windll.kernel32
    kk.GlobalAlloc.restype=ctypes.c_void_p; kk.GlobalLock.restype=ctypes.c_void_p
    kk.GlobalLock.argtypes=[ctypes.c_void_p]; kk.GlobalUnlock.argtypes=[ctypes.c_void_p]
    u.SetClipboardData.argtypes=[ctypes.c_uint,ctypes.c_void_p]
    d=(t+"\0").encode("utf-16le")
    h=kk.GlobalAlloc(0x42,len(d)); p=kk.GlobalLock(h); ctypes.memmove(p,d,len(d)); kk.GlobalUnlock(h)
    u.OpenClipboard(None); u.EmptyClipboard(); u.SetClipboardData(13,h); u.CloseClipboard()

def DOSYA(a):
    tur,_,co=a.partition("|")
    F={"resim":"Resimler (*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp)","ses":"Ses (*.mp3;*.wav;*.ogg;*.m4a;*.flac)","video":"Video (*.mp4;*.webm;*.mkv;*.avi;*.mov)"}
    ft=(F.get(tur,"Medya (*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp;*.mp3;*.wav;*.ogg;*.m4a;*.flac;*.mp4;*.webm;*.mkv;*.avi;*.mov)"),"Tüm dosyalar (*.*)")
    l=dlg("open",directory=os.path.expanduser("~"),allow_multiple=(co=="1"),file_types=ft)
    LOG("DOSYA seçildi: "+json.dumps(l))
    ej("window.ugcoDosya(%s)"%json.dumps([pathlib.Path(p).as_uri() for p in l]))
def METINOKU():
    l=dlg("open",directory=os.path.expanduser("~"),file_types=("Metin dosyaları (*.txt;*.csv;*.json;*.md;*.log;*.ini)","Tüm dosyalar (*.*)"))
    if not l: return
    x=l[0]
    try: t=open(x,encoding="utf-8").read()
    except UnicodeDecodeError: t=open(x,encoding="cp1254",errors="replace").read()
    ej("window.ugcoMetin(%s,%s)"%(json.dumps(t),json.dumps(os.path.basename(x))))
def METINYAZ(a):
    ad,t=json.loads(a)
    l=dlg("save",directory=os.path.expanduser("~"),save_filename=ad or "dosya.txt")
    if not l: return
    with open(l[0],"w",encoding="utf-8") as f: f.write(t)
    ej("window.ugcoKaydedildi(%s)"%json.dumps(l[0]))
def RESIMKAYDET(a):
    ad,d=json.loads(a)
    b=d.partition(",")[2]
    yol=os.path.join(PICS,"".join(ch for ch in ad if ch.isalnum() or ch in "-_")+".jpg")
    with open(yol,"wb") as f: f.write(base64.b64decode(b))
    ej("UGCO.uyari(%s)"%json.dumps("Fotoğraf kaydedildi: "+yol))
WEBS={}; FR={}; RZ=[False]
GIZLI=set(); POP=[0]
def gorun(i): WEBS[i].Visible=(i not in GIZLI and not POP[0])
def adres(u):
    u=u.strip()
    return u if "://" in u else "https://"+u
HOLES={}
def maske_i(i):
    from System.Drawing import Rectangle,Region
    o=WEBS[i]; b=o.Bounds; h=HOLES.get(i) or []
    if not h:
        o.Region=None; return
    cs=win.native.ClientSize; reg=Region(Rectangle(0,0,b.Width,b.Height))
    for x,y,w_,h_ in h: reg.Exclude(Rectangle(int(x*cs.Width)-b.X,int(y*cs.Height)-b.Y,int(w_*cs.Width)+1,int(h_*cs.Height)+1))
    o.Region=reg
def yerlestir(i):
    from System.Drawing import Rectangle
    cs=win.native.ClientSize; l,t,w_,h_=FR[i]
    WEBS[i].Bounds=Rectangle(int(l*cs.Width),int(t*cs.Height),int(w_*cs.Width),int(h_*cs.Height))
    maske_i(i)
def web_isle(k,a):
    d=json.loads(a)
    def run():
        from System import Uri,EventHandler
        from Microsoft.Web.WebView2.WinForms import WebView2,CoreWebView2CreationProperties
        form=win.native
        if not RZ[0]:
            RZ[0]=True
            form.Resize+=EventHandler(lambda s,e:[yerlestir(i) for i in list(WEBS)])
        if k=="WEBTUM":
            POP[0]=0 if d else 1
            for i in list(WEBS): gorun(i)
        elif k=="WEBMASKE":
            HOLES[d[0]]=d[1]
            if d[0] in WEBS: maske_i(d[0])
        elif k=="WEBEKLE":
            o=WEBS.get(d[0])
            if o is None:
                o=WebView2(); cp=CoreWebView2CreationProperties(); cp.UserDataFolder=os.path.join(base,"web"); o.CreationProperties=cp
                o.Source=Uri(adres(d[1])); WEBS[d[0]]=o; form.Controls.Add(o)
            FR[d[0]]=(d[2],d[3],d[4],d[5]); yerlestir(d[0]); GIZLI.discard(d[0]); gorun(d[0]); o.BringToFront()
        elif k=="WEBGIT" and d[0] in WEBS: WEBS[d[0]].Source=Uri(adres(d[1]))
        elif k=="WEBGOR" and d[0] in WEBS:
            GIZLI.discard(d[0]) if d[1] else GIZLI.add(d[0])
            gorun(d[0])
    try:
        from System import Action
        win.native.Invoke(Action(run))
    except Exception:
        LOG(traceback.format_exc())
        if k=="WEBEKLE": ej("UGCO.webYedek(%s,%s)"%(json.dumps(d[0]),json.dumps(adres(d[1]))))
def isle(k,a):
    if k=="KAPAT": win.destroy()
    elif k.startswith("WEB"): web_isle(k,a)
    elif k=="LINK": webbrowser.open(a)
    elif k=="PANO": PANO(a)
    elif k=="DOSYA": DOSYA(a)
    elif k=="METINOKU": METINOKU()
    elif k=="METINYAZ": METINYAZ(a)
    elif k=="RESIMKAYDET": RESIMKAYDET(a)
    pass
class Api:
    def cmd(self,c,p):
        try: isle(c,p)
        except Exception as ex:
            LOG(traceback.format_exc())
            ej("UGCO.uyari(%s)"%json.dumps("Hata ("+c+"): "+str(ex)[:150]))
win=webview.create_window(TITLE,url=pathlib.Path(os.path.join(base,"index.html")).as_uri(),width=W,height=H,fullscreen=FULL,on_top=TOP,js_api=Api(),background_color="#FFFFFF")
webview.start(private_mode=False,storage_path=os.path.join(base,"data"),http_server=False)
